FRAGMENTS = {
    "block-section-order-domain-1": "Домен порядку — чудовий варіант для клірика, який хоче вести свою групу чи підтримувати її. У важких обладунках ви почуваєтеся добре на передовій, а «Голос влади»{{Voice of Authority}} дає суттєвий множник сили{{force multiplier}} кожному в групі, хто завдає великих купок шкоди однією атакою. Проте щоб «Голос влади» був корисним, вам потрібен відповідний член групи з потужними одиночними атаками, тож персонажі, що покладаються на численні відносно дрібні атаки, допомагають менше.",
    "block-section-order-domain-2": "Домен порядку трохи просідає на середніх рівнях. Порядок отримує одну з кращих версій «Божественного удару»{{Divine Strike}}, але вона все одно не дуже пасує Клірику, бо замовляння набагато ефективніші. «Кара порядку»{{Order’s Wrath}} намагається покращити «Божественний удар», але до 17-го рівня замовляння так далеко випереджають його за ефективністю, що користуватися «Карою порядку» стає важко виправдати.",
    "block-section-order-domain-3": "[[1|Гайд Клірика домену порядку]]",
    "block-section-order-domain-4/item/0": "Заклинання домену{{Domain Spells}}: список заклинань коливається між парами фантастичних варіантів і парами ситуативних. Загалом він доволі добрий, і багато заклинань вам знадобляться, особливо заклинання Причарування.",
    "block-section-order-domain-4/item/1": "1-й рівень: обидва — чудові варіанти з широким спектром застосувань, і вони лишаються корисними аж до високих рівнів.",
    "block-section-order-domain-4/item/2": "3-й рівень: <<Hold Person>> ситуативне, але може бути дуже зручним у кампанії з багатьма ворогами-гуманоїдами. <<Zone of Truth>> рідко буває важливою в будь-якій кампанії.",
    "block-section-order-domain-4/item/3": "5-й рівень: базове заклинання клірика й добрий варіант контролю натовпу.",
    "block-section-order-domain-4/item/4": "7-й рівень: обидва заклинання в кращому разі ситуативні.",
    "block-section-order-domain-4/item/5": "9-й рівень: <<Commune>> — одне з моїх найулюбленіших заклинань Віщування, бо воно таке різнобічне й надійне. <<Dominate Person>> формально ситуативне, але якщо в зіткненні є ворог-гуманоїд, важко придумати кращий варіант для накладання.",
    "block-section-order-domain-4/item/6": "Додаткові майстерності{{Bonus Proficiencies}}: важкі обладунки — завжди фантастичний варіант для клірика, а додаткова навичка завжди доречна.",
    "block-section-order-domain-4/item/7": "Голос влади{{Voice of Authority}}: попри багато сміливих спроб, клірики майже ніколи не бувають такими ж добрими в атаках зброєю, як їхні більш орієнтовані на бій союзники. Використовуйте це, щоб дати своєму пройдисвітові шанс завдати «Підступну атаку»{{Sneak Attack}} під час вашого ходу («Підступна атака» діє раз на хід, а не раз на раунд), а якщо в групі немає пройдисвіта, віддайте її тому, хто завдасть найбільше шкоди. Заклинання, яке ви накладаєте, має бути лише заклинанням з рівнем, тож коли ви досягнете достатнього рівня, на якому ваші заклинання низьких рівнів уже не впливатимуть на бій напряму, ви можете використовувати заклинання бонусною дією на кшталт <<Healing Word|Цілющого слова>>, щоб запустити цей ефект, а свою дію витратити на накладання замовляння. Щойно ви отримаєте «Втілення закону»{{Embodiment of Law}}, ви зможете кілька разів на день накладати заклинання Причарування бонусною дією, що дає вам ще більше способів це робити. Це також можна використати для цікавих трюків, якщо ваші друзі випадково мають [[1|одну з кількох рис]].",
    "block-section-order-domain-4/item/8": "{{Божественність: Наказ порядку|Channel Divinity: Order’s Demand}}: роззброюйте кожну ціль у межах 30 футів, що провалила ряткидок Мудрості. Чудово проти ворогів-гуманоїдів, але менш корисно проти монстрів.",
    "block-section-order-domain-4/item/9": "Втілення закону{{Embodiment of Law}}: 3–5 разів на день здається небагато, але з огляду на наголос домену порядку на заклинаннях Причарування цього, імовірно, вистачить, щоб покрити більшість ситуацій, коли ви хочете накласти заклинання Причарування й виконати ще якусь дію в той самий хід.",
    "block-section-order-domain-4/item/10": "Божественний удар{{Divine Strike}}: психічна шкода — серед найнадійніших типів шкоди в грі, але нерозумні істоти на кшталт зомбі й конструктів часто імунні до неї, тож вам знадобляться інші наступальні варіанти для цих ворогів. Дивіться також: [[1|Божественний удар проти замовлянь]].",
    "block-section-order-domain-4/item/11": "Кара порядку{{Order’s Wrath}}: для такого високорівневого уміння це дуже слабко, і воно просто не дотягує до можливостей, які на цьому рівні дає більшість інших доменів. Життя може максимізувати кубики лікування. Природа може командувати армією звірів. Підступність може вдавати, що перебуває в пʼяти місцях одразу, й накладати заклинання з будь-якого з них. Порядок *можливо* завдасть 2к8 шкоди, якщо ви влучите своєю єдиною атакою за хід і поруч буде союзник, щоб вдарити ту саму істоту. Ідеальний сценарій — вдарити ворога зброєю й завдати шкоди «Божественного удару»{{Divine Strike}}, потім бонусною дією накласти заклинання з рівнем, щоб запустити «Голос влади»{{Voice of Authority}}, а союзник влучить по тій самій цілі, щоб запустити бонусну шкоду. Це означає, що ви завдаєте 4к8 психічної шкоди (2к8 від «Божественного удару», 2к8 від «Кари порядку»), плюс те, що завдає ваша зброя, плюс те, що завдає атака вашого союзника. Це непогано, але на цьому рівні <<Sacred Flame>> завдає 4к8 шкоди (більше — інші варіанти на кшталт <<Word of Radiance|Слова сяйва>> чи <<Toll the Dead|Дзвону небіжчика>>), а СК ваших заклинань, імовірно, буде надійнішою за ваш бонус атаки, тож накладання замовляння — значно стабільніше джерело шкоди.",

    "block-section-peace-domain-1": "Забороніть цей домен. Я кажу це не з легким серцем. Забороніть цей домен.",
    "block-section-peace-domain-2": "Домен миру сповнений надзвичайно очевидних випадків зловживання й проблем, що ламають математику гри й можуть перетворити цілком звичайну групу на нестримну силу з неймовірною тактичною ефективністю та абсолютно безглуздими витівками. Одразу з 1-го рівня Домен миру може давати +2к4 до кидків атаки й ряткидків двом членам групи, математично зводячи бій до тривіальності.",
    "block-section-peace-domain-3": "З підвищенням рівня клірика це обмеження у двох осіб поступово розростається на всю групу, а її члени отримують здатність телепортуватися й перенаправляти шкоду з будь-якого джерела, зрештою додаючи опір до цієї шкоди, що фактично дає всій групі постійний опір до шкоди (доки не використано їхню Реакцію) і робить її імунною до захоплень та багатьох інших ефектів контролю натовпу, бо дозволяє їм телепортуватися одне до одного.",
    "block-section-peace-domain-4": "Наслідки цих проблем я розглядаю докладніше в [[1|цьому дописі на Patreon]]. Проблеми масштабні й можуть бути неочевидними, тож мені потрібно три сторінки тексту, щоб пояснити їх усі. Коли я вперше виступив за заборону Домену миру, люди казали, що я збожеволів, а тепер я бачу, як мої аргументи повторюють по всьому інтернету.",
    "block-section-peace-domain-5": "Якщо ви хочете дозволити цей домен у своїй грі, я раджу такі зміни:",
    "block-section-peace-domain-6/item/0": "Зміна правил: до будь-якого кидка к20 можна додати лише один кубик. Більше жодного нашарування <<Bless>>, <<Guidance|Настанови>>, «Бардського натхнення»{{Bardic Inspiration}} і всього іншого. (Я все одно раджу це як домашнє правило; ця проблема існує задовго до Домену миру.)",
    "block-section-peace-domain-7/item/0": "**Зміцнювальний звʼязок{{Emboldening Bond}}**:",
    "block-section-peace-domain-7/item/1": "Якщо істота добровільно атакує іншу істоту зі звʼязку, звʼязок негайно розривається для всіх істот. Ця істота не може входити до іншого «Зміцнювального звʼязку»{{Emboldening Bond}}, доки клірик не завершить тривалий відпочинок. Це запобігає випадкам зловживань, які я описую нижче, коли група може безкоштовно телепортуватися, бʼючи одне одного чи кидаючи каміння.",
    "block-section-peace-domain-7/item/2": "Кількість використань і цілей зростає на ту саму величину й на тих самих рівнях, що й ваш Бонус Майстерності (5-й, 9-й, 13-й і 17-й рівень), але фактично не привʼязана до вашого Бонусу Майстерності. Це лише для запобігання зловживанню мультикласуванням.",
    "block-section-peace-domain-7/item/3": "**Захисний звʼязок{{Protective Bond}}**: розгляньте один із цих варіантів:",
    "block-section-peace-domain-7/item/4": "Той, хто ним користується, негайно втрачає переваги «Зміцнювального звʼязку»{{Emboldening Bond}} на решту дії ефекту, що дозволяє пожертвувати власними перевагами, щоб урятувати союзника від потенційно смертельного джерела шкоди.",
    "block-section-peace-domain-7/item/5": "Розділіть шкоду між початковим одержувачем і тим, хто витрачає свою Реакцію, щоб активувати «Захисний звʼязок»{{Protective Bond}}, за тими самими правилами, що й заклинання <<Warding Bond>>.",
    "block-section-peace-domain-7/item/6": "**Потужне заклинання{{Potent Spellcasting}}**: зважаючи на тему, я щиро не знаю, чому воно тут. Залиште його як дивацтво або замініть чимось новим — наприклад, дозволом накладати <<Guidance|Настанову>> на відстані 30 футів.",
    "block-section-peace-domain-8/item/0": "**Розширений звʼязок{{Expansive Bond}}**: приберіть механіку опору. Подвоєння дальності — більш ніж достатньо, зважаючи на те, наскільки добрий уже «Зміцнювальний звʼязок»{{Emboldening Bond}}.",
    "block-section-peace-domain-9": "З цими змінами це чудовий підклас підтримки. <<Warding Bond>> по-справжньому підкреслює командну роботу й тримання разом і дає фантастичні переваги за це. «Зміцнювальний звʼязок»{{Emboldening Bond}} корисний протягом усієї карʼєри, а ваша здатність застосовувати його до більшої кількості цілей з підвищенням рівня — неймовірно корисна на додачу до зростаючих переваг. Якщо хочете грати заклинача підтримки з тилу, тут важко схибити.",
    "block-section-peace-domain-10": "Попри назву домену, тут мало що стосується «миру». Звісно, жоден із варіантів класу не наступальний (крім «Потужного заклинання»{{Potent Spellcasting}}, яке тут незрозуміло чому присутнє), але головна функція Домену миру — робити вашу групу жорстоких убивць ефективнішою в чиненні насильства. Звісно, вам не доведеться бруднити руки, але це вас не виправдовує.",
    "block-section-peace-domain-11/item/0": "Заклинання домену{{Domain Spells}}: здебільшого варіанти лікування й захисту, але в сукупності заклинання розвʼязують різноманітні проблеми, з якими стикається група авантюристів у типових пригодах. З правильним заклинанням зі списку Домену миру ви можете запобігти більшості проблем, що можуть спіткати вашу групу, або усунути їх, за винятком власне шкоди ХП, бо жодне заклинання Домену миру не відновлює ХП. На щастя, ви все ще можете розраховувати на свій звичайний запас заклинань, а «Божественність: Бальзам миру»{{Channel Divinity: Balm of Peace}} дає трохи додаткового лікування.",
    "block-section-peace-domain-11/item/1": "1-й рівень: чудові захисні варіанти для себе чи союзника.",
    "block-section-peace-domain-11/item/2": "3-й рівень: <<Aid>> настільки добре, що багато хто готує його щодня, тож отримати його безкоштовно — фантастично. <<Warding Bond>> ситуативніше, але оскільки Домен миру — підклас клірика з тилу, у вас великий запас ХП, який ви мало на що витрачаєте, тож можете поділитися ним із тим, хто виконує в групі роль танка.",
    "block-section-peace-domain-11/item/3": "5-й рівень: два ситуативні варіанти, якими ви навряд чи користуватиметеся щодня.",
    "block-section-peace-domain-11/item/4": "7-й рівень: ситуативне захисне підсилення й заклинання «пройди ряткидок або страждай»{{save-or-suck}}, що по суті є «бульбашкою тайм-ауту».",
    "block-section-peace-domain-11/item/5": "9-й рівень: <<Greater Restoration>> корисне лише ситуативно, але це необхідний варіант зцілення, тож приємно мати його напоготові. <<Rary's Telepathic Bond>> — величезна перевага для авантюристів, і користуватися ним слід часто.",
    "block-section-peace-domain-11/item/6": "Знаряддя миру{{Implement of Peace}}: безкоштовна навичка завжди доречна. Аналіз Поведінки зазвичай чудовий вибір для Клірика, бо він базується на Мудрості, але Переконання теж дуже корисне.",
    "block-section-peace-domain-11/item/7": "Зміцнювальний звʼязок{{Emboldening Bond}}: це приголомшливо. По суті це <<Bless>>, але з тривалістю 10 хвилин, і воно також діє на перевірки характеристик. Щоправда, <<Bless>> корисніше для істот, що роблять більше однієї атаки за хід, але це нормально. *Вони складаються.* Повторю ще раз: *«Зміцнювальний звʼязок» і <<Bless>> складаються.* На 1-му рівні оберіть двох людей, і вони отримають +2к4 до атак і ряткидків. У середньому це *подвоює* очікуваний бонус атаки персонажа 1-го рівня, а ряткидки стають значно менш загрозливими. Ще краще те, що все це прогресує залежно від вашого Бонусу Майстерності. Якщо ви взяли один рівень клірика й більше не повернулися, ви так само добрі з цим умінням, як клірик того ж рівня. «Зміцнювальний звʼязок» — центральне уміння Домену миру, а те, кого включити до звʼязку, — надзвичайно важливе тактичне рішення для Клірика домену миру. Оскільки Бонус Майстерності росте так повільно, ви не зможете охопити повну групу з 4 осіб до 9-го рівня. Це дещо обмежує переваги, але якщо ви тримаєтеся осторонь неприємностей і спираєтеся на замовляння з ряткидком на кшталт <<Sacred Flame|Священного полумʼя>>, у вас мало причин самому входити до звʼязку. Накладайте його на союзників на передовій і поступово додавайте союзників із тилу в міру зростання вашого Бонусу Майстерності.",
    "block-section-peace-domain-11/item/8": "{{Божественність: Бальзам миру|Channel Divinity: Balm of Peace}}: небагато лікування, особливо порівняно з чимось на кшталт «Божественність: Збереження життя»{{Channel Divinity: Preserve Life}}, але якщо ваша група достатньо щільна, ви можете зачепити всіх її членів і всіх улюбленців чи викликаних істот однією дією, особливо якщо у вас велика швидкість і ви літаєте (кентаври й ааракокри чудово для цього підходять). На низьких рівнях це може запобігти повній загибелі групи (TPK). Це також чудовий спосіб витратити залишені використання «Каналу божественності»{{Channel Divinity}} перед відпочинком. Проте з набуттям рівнів його корисність у бою зменшуватиметься, і це стане тим, що ви використовуєте перед короткими відпочинками, щоб заощадити на витраті кісток хітів.",
    "block-section-peace-domain-11/item/9": "Захисний звʼязок{{Protective Bond}}: фантастичний і для захисту тендітних союзників на кшталт заклиначів (включно, потенційно, з вами), і для швидкого переставлення союзників. Окрім їхньої Реакції, обмежень на те, як часто його можна використовувати, немає, і в разі потреби можна зробити беззбройний удар по союзнику й використати «Захисний звʼязок», щоб перетягнути іншого союзника впритул до цілі. Це справді витрачає Реакцію істоти, що телепортується, але для багатьох персонажів така ціна абсолютно варта того. Коли в людей є зайві невикористані реакції, це може часто вживатися в бою. Якщо ж група сильно вкладається у власні реакції, воно може лишитися невикористаним, бо той, хто хоче прийняти удар, уже витратив свою реакцію на атаку з риси «Майстер древкової зброї»{{Polearm Master}}, а той, по кому бʼють, просто накладе <<Shield>>, щоб КБ 24 узагалі не дав атаці завдати шкоди. Поза боєм воно має корисність як телепортація. Якщо у вашій групі є фамільяр, ви можете включити фамільяра у свій «Зміцнювальний звʼязок»{{Emboldening Bond}} (якщо у вас є місце, що виправдовує це). Фамільяри мають лише одне ХП, тож навіть найменша шкода їх убиває, а власник фамільяра має вкласти час і золото, щоб повернути його. «Захисний звʼязок» дозволяє і зберегти фамільяра живим, і використати його як потенційно літаючий телепортаційний маяк. Відправте фамільяра туди, куди вам треба, киньте в нього камінь, тоді телепортуйтеся до нього й поглиньте шкоду. Союзники у вашому звʼязку можуть так само бити самі себе, щоб запустити телепортацію. Увесь звʼязок може навіть телепортуватися від одного удару: просто нехай кожен реагує на шкоду від попереднього тригера реакції. Ще один приклад витівок: Варвар Шляху тотемного воїна до цього рівня може мати опір до всієї шкоди під час люті. Додайте <<Heroism>> (а ще краще — другого Клірика домену сутінків із «Божественність: Святилище присмерку»{{Channel Divinity: Twilight Sanctuary}}) поверх цього — і він майже нескінченна гора ХП, що може використовувати свою Реакцію щоходу, щоб радо приймати шкоду за решту групи, зручно вдвічі зменшуючи всю шкоду, яку отримує, і водночас насолоджуючись постійно відновлюваним запасом тимчасових ХП від <<Heroism>>.",
    "block-section-peace-domain-11/item/10": "Потужне заклинання{{Potent Spellcasting}}: до цього рівня ви легко можете мати Мудрість 20, що дає чудове підсилення вашій шкоді. Зауважте, що воно діє лише на замовляння Клірика, тож ви не можете поєднувати його з рисою «Посвячений у магію»{{Magic Initiate}} чи замовляннями, отриманими мультикласуванням.",
    "block-section-peace-domain-11/item/11": "Розширений звʼязок{{Expansive Bond}}: зважаючи, що «Захисний звʼязок»{{Protective Bond}} не має обмежень на використання, крім витрати Реакції, це простий спосіб фактично дати всій групі опір до всієї шкоди, перекидаючи шкоду між членами групи. Доки в усіх пристойний запас ХП (Чарівникам, можливо, доведеться дбати про себе), кожен може трохи пожертвувати заради значної вигоди для всієї групи.",

    "block-section-tempest-domain-1": "Буря водночас наступальна й витривала, розташовуючись десь між живучістю Домену життя і шкодою Домену світла. Уміння й заклинання Бурі дають кілька цікавих варіантів контролю натовпу, контролю території й шкоди по області, що дозволяє Клірику Бурі бути ефективною загрозою як на близькій, так і на дальній дистанції. Домен бурі не дає утилітарних варіантів чи варіантів підтримки, тож розраховуйте спиратися на свій список заклинань для розвʼязання проблем, які не розвʼязати ударом.",
    "block-section-tempest-domain-2": "[[1|Гайд Клірика домену бурі]]",
    "block-section-tempest-domain-3/item/0": "Заклинання домену{{Domain Spells}}: жменя утилітарних варіантів, але переважно заклинання шкоди. У клірика немає багато вбудованих варіантів блискавичної чи громової шкоди, тож це чудові доповнення разом з іншими уміннями Домену бурі.",
    "block-section-tempest-domain-3/item/1": "1-й рівень: <<Fog Cloud>> — чудовий механізм втечі чи контролю натовпу. <<Thunderwave>> спокушає, коли ви опинилися в ближньому бою не за силами й вам треба вибороти трохи простору чи вирватися із захоплення, але памʼятайте, що це ряткидок Статури, а вони зазвичай високі.",
    "block-section-tempest-domain-3/item/2": "3-й рівень: <<Gust of Wind>> дуже ситуативний, але <<Shatter>> — це по суті «полегшена» версія <<Fireball|Вогнекулі>>; до того ж він працює з «Божественність: Руйнівний гнів»{{Channel Divinity: Destructive Wrath}}, тож можна максимізувати шкоду.",
    "block-section-tempest-domain-3/item/3": "5-й рівень: <<Sleet Storm>> — посереднє заклинання контролю натовпу, а <<Call Lightning>> дратує й може бути дуже важким для ефективного використання. Зауважте, що «Божественність: Руйнівний гнів»{{Channel Divinity: Destructive Wrath}} діє лише на один кидок шкоди, а не на все заклинання, тож використовувати його з <<Call Lightning|Накликанням блискавки>> здебільшого безглуздо.",
    "block-section-tempest-domain-3/item/4": "7-й рівень: <<Ice Storm>> — погане заклинання, а <<Control Water>> корисне лише тоді, коли поруч є велика водойма, що в більшості кампаній трапляється нечасто.",
    "block-section-tempest-domain-3/item/5": "9-й рівень: <<Destructive Wave>> завдає чудової шкоди типів, до яких дуже рідко є опір, але оскільки тип шкоди розділений, «Божественність: Руйнівний гнів»{{Channel Divinity: Destructive Wrath}} максимізує лише половину кубиків шкоди. За той самий слот заклинання 5-го рівня <<Shatter>> завдає 6к8 шкоди (максимізується до 48), тоді як <<Destructive Wave>> завдає в середньому 47,5 (30 максимізовано плюс 17,5 у середньому) у значно більшій області дії, водночас виключаючи ваших союзників, тож <<Destructive Wave>> усе одно перемагає <<Shatter>> у переважній більшості ситуацій. На жаль, <<Destructive Wave>> не виграє від накладання вищим слотом, бо задумана як заклинання Паладина. <<Insect Plague>> — фантастичний варіант контролю території, але частково дублює <<Spirit Guardians|Духів захисників>>. <<Insect Plague>> використовує більші кубики шкоди, але через масштабування слотом завдає приблизно стільки ж шкоди, як <<Spirit Guardians>>. Обидва заклинання мають тривалість 10 хвилин і вимагають Концентрації. <<Insect Plague>> накладається на відстані й має більшу область дії, тож вам не треба стояти посеред області, але й перемістити її ви не можете. Ці два заклинання приблизно рівноцінні, але виграють у різних ситуаціях.",
    "block-section-tempest-domain-3/item/6": "Додаткові майстерності{{Bonus Proficiencies}}: важкі обладунки чудові для Клірика. Бойова зброя додає ще кілька бойових варіантів, але клірики погано користуються зброєю, і бойова зброя цього не змінює. Із важкими обладунками та «Гнівом бурі»{{Wrath of the Storm}} можна обрати дворучну зброю, хоч замовляння й надалі будуть ефективнішими, коли ви здобуватимете рівні й додаватимете додаткові кубики шкоди.",
    "block-section-tempest-domain-3/item/7": "Гнів бурі{{Wrath of the Storm}}: на низьких рівнях він прямо вбиватиме ворогів. На високих рівнях це лише легкий стримувальний чинник.",
    "block-section-tempest-domain-3/item/8": "{{Божественність: Руйнівний гнів|Channel Divinity: Destructive Wrath}}: чудово, коли вам абсолютно необхідно накласти <<Shatter>> на кожного ворога в кімнаті. Не спокушайтеся використовувати це з «Гнівом бурі»{{Wrath of the Storm}}; це трагічна марнота чудового уміння. На жаль, у списку заклинань Клірика дуже мало заклинань, що для цього підходять, тож найкращі варіанти — зі списку заклинань вашого домену, якщо ви не мультикласуєтеся.",
    "block-section-tempest-domain-3/item/9": "Удар блискавки{{Thunderbolt Strike}}: добре поєднується з «Гнівом бурі»{{Wrath of the Storm}}, коли вам з якоїсь причини треба вийти з ближнього бою, а оскільки «Гнів бурі» й за успішного ряткидка завдає половину шкоди, ефект відштовхування вам гарантований. На жаль, у кліриків немає жодного замовляння, що завдає блискавичної шкоди. Це було б чудово, якби працювало з блискавичною *чи* громовою шкодою, але ні. Як і багато подібних ефектів, воно лише вказує, що ви відштовхуєте ціль «геть», а не «прямо геть». Це означає, що ви вільні відштовхнути її вгору й геть, потенційно підкидаючи ворогів на 10 футів у повітря й змушуючи їх упасти на 10 футів від місця, де вони були раніше.",
    "block-section-tempest-domain-3/item/10": "Божественний удар{{Divine Strike}}: громова шкода — серед найкращих типів шкоди в грі, але клірики все одно погано користуються зброєю. Дивіться також: [[1|Божественний удар проти замовлянь]] вище.",
    "block-section-tempest-domain-3/item/11": "Народжений бурею{{Stormborn}}: майже постійний політ! Політ абсолютно вирішальний на високих рівнях, а отримати його так легко може звільнити ресурси для цікавіших речей. Ви не зможете користуватися цим усередині підземель та інших поширених місць пригод, але це все одно дуже корисно.",

    "block-section-trickery-domain-1": "Підступність пропонує чудовий список заклинань, але класові уміння важко ефективно використовувати. Це нелегкий підклас для гри, але досвідчений гравець може перетворити Домен підступності на потужного заклинача підтримки й утиліт. З невеликими зусиллями можна також успішно вскочити в ближній бій, але це зазвичай не основний варіант для Домену підступності.",
    "block-section-trickery-domain-2": "Мультикласування в пройдисвіта — цікавий варіант для Домену підступності. Чаротворство Домену підступності дуже схоже на Містичного спритника, а багато умінь Домену підступності чудово поєднуються з класовими уміннями Пройдисвіта. Якщо ви обираєте цей шлях, я раджу почати з одного рівня пройдисвіта, щоб отримати більше володінь навичками, і будувати персонажа навколо Спритності й Мудрості. Ще два рівні для отримання підкласу можуть допомогти, якщо ви хочете чогось на кшталт <<Booming Blade|Гримучого Клинка>>, але це не обовʼязково, хіба що ви точно хочете йти в ближній бій.",
    "block-section-trickery-domain-3": "Проте це занурення в клас аж ніяк не обовʼязкове. Багато проблем, які Пройдисвіт розвʼязує буденними засобами, можна розвʼязати заклинаннями зі списку Домену підступності, як-от <<Disguise Self>> (замінює набори для маскування), <<Charm Person>> (замінює навички «обличчя») і <<Pass Without Trace>> (замінює або принаймні підсилює Непомітність).",
    "block-section-trickery-domain-4": "[[1|Гайд домену підступності]]",
    "block-section-trickery-domain-5/item/0": "Заклинання домену{{Domain Spells}}: багато справді цікавих варіантів, чимало з яких зазвичай недоступні Клірикам.",
    "block-section-trickery-domain-5/item/1": "1-й рівень: <<Disguise Self>> і <<Charm Person>> можуть розрядити чимало соціальних ситуацій. <<Charm Person>> не може повністю замінити справжнє «обличчя», але підходить дуже близько.",
    "block-section-trickery-domain-5/item/2": "3-й рівень: <<Mirror Image>>, можливо, краще за пристойний КБ, а <<Pass Without Trace>> перетворює групу гупаючих Воїнів на мандрівну кулю тихого вбивства.",
    "block-section-trickery-domain-5/item/3": "5-й рівень: <<Blink>> дає вам 50% шансу, що вас не можна буде обрати ціллю між ходами, що чудово, бо ви, імовірно, лікар групи, тож бути недосяжним для союзників коштує вам дуже мало, а небажаної уваги ви не привертаєте. <<Dispel Magic>> формально ситуативне, але таке корисне й важливе, що не підготувати його часто може бути смертельною помилкою.",
    "block-section-trickery-domain-5/item/4": "7-й рівень: <<Dimension Door>> — добра телепортація на коротку відстань, яку переважна більшість кліриків просто не може відтворити. <<Polymorph>> — один із найуніверсальніших ефектів у грі, і з правильною формою звіра дозволяє розвʼязати найрізноманітніші проблеми. Памʼятайте, що накладати його на себе не обовʼязково, тож перетворити союзника на динозавра й їздити на ньому — цілком реальний варіант.",
    "block-section-trickery-domain-5/item/5": "9-й рівень: <<Modify Memory>> дуже ситуативне, але <<Dominate Person>> — чудовий спосіб перетворити потужного ворога-гуманоїда на кумедного вихованця на цілу хвилину.",
    "block-section-trickery-domain-5/item/6": "Благословення хитруна{{Blessing of the Trickster}}: на себе його застосувати не можна, тож або накладайте його на того, хто в групі здіймає купу шуму, тупаючи в важких обладунках, або на розвідника групи й відправляйте його самого. Разом із <<Pass Without Trace|Переміщенням без сліду>> перевірки Непомітності для вашої групи майже гарантовано успішні.",
    "block-section-trickery-domain-5/item/7": "{{Божественність: Заклик двійника|Channel Divinity: Invoke Duplicity}}: це може бути складно ефективно використовувати, але коли ви в цьому розберетеся, воно дуже потужне. Памʼятайте, що воно вимагає Концентрації, тож його не можна поєднувати з базовими варіантами клірика на кшталт <<Spirit Guardians|Духів захисників>>, а оскільки для переміщення двійника використовується ваша бонусна дія, вам може бути важко застосовувати його одночасно з <<Spiritual Weapon|Духовною зброєю>>. Найкращий сценарій — розмістити ілюзію десь на видноті, поки ви ховаєтеся поблизу, і використовувати ілюзію як точку початку для заклинань малої дальності. Варіанти на кшталт <<Word of Radiance|Слова сяйва>> набагато безпечніші, коли ви можете завести свою ілюзію в натовп ворогів, щоб накласти його, а оскільки ілюзія — не істота, її не турбують принагідні атаки, ефекти контролю території чи навіть ворожі істоти, що блокують простір. Ви можете використати ілюзію, щоб отримати Перевагу на кубику в ближньому бою, але я нервуюся, радячи робити це основною тактикою. Лише в середніх обладунках ви не такий живучий, як інші клірики на передовій, а атаки зброєю здебільшого не найкращий варіант для кліриків. Легкий доступ до Переваги може зробити зброю життєздатною порівняно із замовляннями (що для більшості кліриків дуже важко), особливо після отримання «Божественного удару»{{Divine Strike}}, але не дозволяйте цьому змусити вас будувати персонажа навколо ближнього бою. Це, що примітно, стосується всіх атак, тож Перевага компенсує Перешкоду на кубику за дальні атаки, а також застосовується до атак заклинаннями, тож ви можете доставляти заклинання на кшталт <<Inflict Wounds>> і <<Spiritual Weapon|Духовної зброї>> з Перевагою. Якщо вас влаштовує використовувати свого ілюзорного двійника як відволікання й курʼєра для своїх заклинань, ви можете повністю ігнорувати частину про Перевагу в «Заклику двійника» і все одно впораєтеся чудово. Дивно, але «Заклик двійника» не дає подробиць про те, як поводитися із взаємодією з ілюзорним двійником. Що буде, якщо ілюзію атакують? Чи можуть істоти не вірити в неї, і якщо так, як вони тоді сприймають ілюзію? Якщо істоти знають, що двійник — ілюзія, чи отримуєте ви Перевагу на атаках, коли ви з двійником поруч з істотою? Джеремі Кроуфорд підтвердив, що двійник [[1|імунний до шкоди, а зброя проходить крізь нього]], але це єдина корисна відповідь за правилами, яку я знайшов на цю тему.",
    "block-section-trickery-domain-5/item/8": "{{Божественність: Плащ тіней|Channel Divinity: Cloak of Shadows}}: невидимість чудова, але одного раунду просто замало. Надзвичайно прикро, що це єдиний варіант невидимості в Домену підступності.",
    "block-section-trickery-domain-5/item/9": "Божественний удар{{Divine Strike}}: отруйна шкода — один із типів шкоди, до яких у грі найчастіше є опір, та імунітет теж поширений. Майте замовляння шкоди для ворогів на кшталт нежиті й конструктів. Дивіться також: [[1|Божественний удар проти замовлянь]] вище.",
    "block-section-trickery-domain-5/item/10": "Удосконалений двійник{{Improved Duplicity}}: дозволяє тримати двійників поруч з усіма вашими союзниками, щоб підсилювати чи лікувати їх заклинаннями з дистанцією «Дотик», тримати ворогів у розгубленості щодо вашого положення й, в ідеалі, обманом змусити їх марнувати атаки/заклинання на ваших двійників, доставляти заклинання малої дальності на кшталт <<Harm|Шкоди>> з безпечної відстані та переміщатися між цілями, отримуючи Перевагу на кубику в атаках ближнього бою проти них.",

    "block-section-twilight-domain-1": "Дуже всебічний підклас: клірик домену сутінків процвітає на передовій, де може і ефективно захищати союзників, і бути пристойною загрозою. Його уміння — переважно підсилення, утиліти й захисні варіанти, а наступ — здебільшого другорядна справа, але «Божественність: Святилище присмерку»{{Channel Divinity: Twilight Sanctuary}} робить клірика домену сутінків ідеальним варіантом для групи, повної «скляних гармат».",
    "block-section-twilight-domain-2": "Тактика Домену сутінків надзвичайно проста. Тримайте «Благословення пильності»{{Vigilant Blessing}} активним на випадок початку бою. Коли бій починається, починайте зі «Святилища присмерку»{{Twilight Sanctuary}} і тримайте союзників у радіусі, щоб захищати їх тимчасовими ХП. На відкритих місцевостях це означатиме рух разом із групою, щоб вступити в ближній бій чи битися на відстані, тож будьте готові до таких ситуацій. Далі робіть звичайні клірикові речі: розмахуйте зброєю чи накладайте заклинання.",
    "block-section-twilight-domain-3": "[[1|Гайд підкласу Клірика домену сутінків]]",
    "block-section-twilight-domain-4/item/0": "Заклинання домену{{Domain Spells}}: майже самі добрі варіанти, але жменя ситуативних, які вам може бути важко застосувати.",
    "block-section-twilight-domain-4/item/1": "1-й рівень: найнижчорівнева протидія невидимості й базовий варіант «пройди ряткидок або страждай»{{save-or-suck}} для низьких рівнів. <<Sleep>> після низьких рівнів перестане бути надійно корисним, але <<Faerie Fire>> ніколи не перестає працювати.",
    "block-section-twilight-domain-4/item/2": "3-й рівень: <<See Invisibility>> — ще одна чудова протидія невидимості, а наявність <<Faerie Fire|Вогників фей>> під рукою дозволяє легко помітити невидимих ворогів і тоді виявити їх групі, не маючи на всіх активного <<See Invisibility>>. <<Moonbeam>> — чудовий бойовий варіант для вузького вікна рівнів 3 і 4, поки не зросла шкода ваших замовлянь, а <<Sacred Flame>> не стане майже так само ефективним, як заклинання 2-го рівня, що вимагає Концентрації. Після цього ви ніколи не використовуватимете його, хіба що зустрінете перевертня.",
    "block-section-twilight-domain-4/item/3": "5-й рівень: величезні обсяги повільного лікування, збалансовані під накладання Паладином високого рівня, і магічне місце для відпочинку, що водночас є основним варіантом, коли ви просто неба й потребуєте укриття. На середніх рівнях одна <<Aura of Vitality>> може фактично замінити все лікування, яке група отримала б від короткого відпочинку, і не відчуватиметься як велика витрата ресурсів. Якщо в групі немає інших ресурсів, що відновлюються на короткому відпочинку, витрата хвилини на ходьбу й повернення до повного ХП дозволяє легко випередити [[1|очікуваний темп]] і стати епічними ще швидше.",
    "block-section-twilight-domain-4/item/4": "7-й рівень: <<Aura of Life>> зазвичай корисна лише проти певних типів нежиті на кшталт тіней, але <<Greater Invisibility>> — одне з найкращих підсилень у грі.",
    "block-section-twilight-domain-4/item/5": "9-й рівень: <<Circle of Power>> зазвичай ексклюзив Паладина, а ви отримуєте його задовго до нього. <<Mislead>> гарне, але дуже ситуативне.",
    "block-section-twilight-domain-4/item/6": "Додаткові майстерності{{Bonus Proficiencies}}: ідеально для клірика на передовій.",
    "block-section-twilight-domain-4/item/7": "Очі ночі{{Eyes of Night}}: темний зір чудовий, якщо у вас його ще немає, а абсолютно абсурдна дальність 300 фт. безпрецедентна. 120 фт. були б синім. Крім того, ви можете ділитися ним із союзниками на годину за раз і можете відновити здатність, витративши слот заклинання будь-якого рівня. Зважаючи, що заклинання <<Darkvision>> — 2-го рівня, це феноменально.",
    "block-section-twilight-domain-4/item/8": "Благословення пильності{{Vigilant Blessing}}: але почекайте, це ще не все! На додачу до іншого дивовижного, що Домен сутінків отримує на першому рівні, ви можете дати комусь Перевагу на кубику на його наступний кидок Ініціативи. Я раджу Пройдисвіта-Убивцю, якщо такий є у вашій групі, а інакше обирайте одного з основних контролерів поля бою у вашій групі, навіть якщо це ви. Ефект діє, доки не закінчиться, тож варто налаштовувати його знову щойно закінчується бій, щоб ви ніколи не були без цієї переваги.",
    "block-section-twilight-domain-4/item/9": "{{Божественність: Святилище присмерку|Channel Divinity: Twilight Sanctuary}}: якби це був ефект «вистрілив і забув», що давав би тимчасові ХП чи один раз знімав причарування/страх, я б оцінив його синім, бо запас тимчасових ХП величезний. Натомість він оновлюється щораунду протягом хвилини. Памʼятайте, що клірики можуть використовувати «Канал божественності»{{Channel Divinity}} раз на короткий відпочинок на цьому рівні, зростаючи до 3 разів на короткий відпочинок. Це робить усю вашу групу неймовірно важкою для вбивства й майже імунною до ефектів і причарування, і страху. Ефект світла тут трохи неясний, бо не пояснюється, як він взаємодіє з іншими джерелами світла. Чи зменшує він наявні рівні освітлення? Як він взаємодіє з магічним світлом? А із заклинаннями на кшталт <<Daylight|Денного світла>> чи <<Darkness|Темряви>>? Чесно кажучи, я не певен і вагаюся давати поради. Можливо, яскравіше світло просто перекриває світло від «Святилища присмерку», і якщо так, я доволі впевнений, що це не створює жодних проблем, окрім спроби активувати «Кроки ночі»{{Steps of Night}}. Це уміння виняткове за потужністю. Кількість тимчасових ХП величезна, а те, що вона оновлюється, лякає. Якщо це проблема у вашій грі (а вона може виникнути з середини гри, коли двічі за короткий відпочинок здається не надто цінним, щоб використовувати часто), є кілька варіантів, якими можна її розвʼязати. Якщо ви спробуєте будь-який із них або маєте власні виправлення, [[1|напишіть мені]] і розкажіть, що пробували й як це пройшло.",
    "block-section-twilight-domain-4/item/10": "**Виправлення A**: клірик має підтримувати Концентрацію, ніби концентрується на заклинанні. Це не дозволяє поєднувати «Святилище присмерку»{{Twilight Sanctuary}} з найкращими заклинаннями Клірика, як-от <<Bless>> і <<Spirit Guardians>>.",
    "block-section-twilight-domain-4/item/11": "**Виправлення B**: застосування будь-якого з двох ефектів забирає Реакцію клірика, тож він може впливати лише на одну істоту за раунд.",
    "block-section-twilight-domain-4/item/12": "**Виправлення C**: варіант із тимчасовими ХП діє один раз на істоту, а тимчасові ХП зникають, якщо істота залишає область дії.",
    "block-section-twilight-domain-4/item/13": "**Виправлення D**: відкоригуйте кількість наданих тимчасових ХП. 1к6+рівень — це багато. Спробуйте 1к6+Мудрість (на низьких рівнях може бути трохи вище за задумане, але до 8-го рівня сягне максимуму 1к6+5). Можна також спробувати просто 1к6 чи лише модифікатор Мудрості клірика.",
    "block-section-twilight-domain-4/item/14": "**Виправлення E**: замість автоматичного зняття ефекту Причарування/Страху істоти можуть повторити ряткидок проти одного ефекту Причарування/Страху, що наразі на них діє, з початковою СК ряткидка. Якщо це здається надто великим «послабленням», можна дати Перевагу на кубику на ряткидок.",
    "block-section-twilight-domain-4/item/15": "**Виправлення F**: тимчасові ХП, надані «Святилищем присмерку»{{Twilight Sanctuary}}, закінчуються, коли завершується ефект або якщо істота залишає область дії.",
    "block-section-twilight-domain-4/item/16": "Кроки ночі{{Steps of Night}}: магічний політ — вирішальний тактичний варіант, а активувати його бонусною дією без витрат слотів заклинань — феноменально. Щоправда, запустити його можна лише в тьмяному світлі й темряві, але тьмяне світло можна створити за допомогою «Божественність: Святилище присмерку»{{Channel Divinity: Twilight Sanctuary}}, а в темному місці можна потримати свічку. Уміння також не вимагає лишатися в таких умовах освітлення, щоб продовжувати ним користуватися. Ви можете користуватися ним щодня стільки разів, скільки становить ваш Бонус Майстерності, — цього зазвичай досить для всіх випадків, коли вам абсолютно необхідно літати.",
    "block-section-twilight-domain-4/item/17": "Божественний удар{{Divine Strike}}: променева шкода — серед найнадійніших доступних типів шкоди. Дивіться також: [[1|Божественний удар проти замовлянь]].",
    "block-section-twilight-domain-4/item/18": "Покров присмерку{{Twilight Shroud}}: фактично +2 до КБ для всієї вашої групи. Математично відчутно на будь-якому рівні, і воно досі складається з переважною більшістю інших підсилень КБ. Ваші союзники також можуть використовувати це укриття, щоб ховатися, але уточніть у свого Майстра.",

    "block-section-war-domain-1": "Клірик війни трохи скорочує розрив у бойових можливостях між Кліриком і Паладином, трохи більше наголошуючи на бойовій майстерності на передовій, ніж на чаротворстві. Хоч це цікава концепція з кількома чудовими варіантами, часто важко використовувати варіанти Домену війни разом, бо багато з них залежать від Концентрації та/або бонусних дій.",
    "block-section-war-domain-2": "Слабке місце Домену війни — його спроба спертися на використання зброї. Зброя математично гірша за замовляння, а витрата заклинань і «Каналу божественності»{{Channel Divinity}}, щоб змусити її працювати, мало допомагає. «Священик війни»{{War Priest}} дозволяє атакувати бонусною дією кілька разів на день, що достатньо спокушає, щоб Домен війни здавався привабливим, але після низьких рівнів ви побачите, що більшість підкласових умінь вам не дуже допомагає. Список заклинань непоганий, але найкращі варіанти в ньому — це все вже клірикові заклинання, тож усе, що він робить, — позбавляє вас клопоту готувати ці заклинання.",
    "block-section-war-domain-3": "Виправлення Домену війни вимагає виправлення зброї для кліриків, а це вимагає виправлення «Божественного удару»{{Divine Strike}}. Можливо, достатньо просто змінити прогресію шкоди «Божественного удару». Спробуйте +1к6 на 5-му рівні, а потім додавайте к6 на 11-му й 17-му рівнях.",
    "block-section-war-domain-4": "[[1|Гайд Клірика домену війни]]",
    "block-section-war-domain-5/item/0": "Заклинання домену{{Domain Spells}}: багато справді фантастичних варіантів, але більше половини заклинань домену вимагають Концентрації, через що важко використати більше одного чи двох за бій.",
    "block-section-war-domain-5/item/1": "1-й рівень: <<Divine Favor>> не залишиться корисною після низьких рівнів, але на низькому рівні це приємна порція додаткової шкоди з пристойною тривалістю, що коштує бонусної дії для накладання. <<Shield of Faith>> залишатиметься корисним на кожному рівні. +2 до КБ — це багато в пʼятій редакції, а 10 хвилин — фантастична тривалість для слота заклинання. Проте воно вимагає Концентрації, а отже, його не можна поєднувати з іншими чудовими підсиленнями низьких рівнів на кшталт <<Bless>>.",
    "block-section-war-domain-5/item/2": "3-й рівень: оскільки <<Magic Weapon>> вимагає Концентрації, його зазвичай варто використовувати лише тоді, коли у вас немає постійної магічної зброї, і лише проти ворогів, що мають опір до немагічної зброї. <<Spiritual Weapon>> — базовий варіант клірика й чудовий спосіб перетворити бонусну дію на шкоду без потреби в Концентрації.",
    "block-section-war-domain-5/item/3": "5-й рівень: <<Crusader's Mantle>> — це <<Divine Favor>> для всієї групи. Шкода за атаку все ще мала, але якщо хтось користується «Боєм двома зброями»{{Two-Weapon Fighting}}, союзники мають «Додаткову атаку»{{Extra Attack}} або просто велика група, вигода швидко накопичується. Але загалом воно не може конкурувати з <<Spirit Guardians|Духами захисниками>>, які ви теж отримуєте. <<Spirit Guardians>> є серед найефективніших варіантів шкоди в грі, і багато кліриків готують їх щодня.",
    "block-section-war-domain-5/item/4": "7-й рівень: <<Stoneskin>> — фантастичне підсилення, але вона дуже дорога й не допоможе вам, щойно ви отримаєте «Аватар битви»{{Avatar of Battle}}. <<Freedom of Movement>> корисна ситуативно.",
    "block-section-war-domain-5/item/5": "9-й рівень: <<Flame Strike>> — пристойне заклинання шкоди по області, але за той самий слот заклинання я б набагато охочіше накладав <<Spirit Guardians>> і йшов у бій. <<Hold Monster>> — просте заклинання «пройди ряткидок або страждай»{{save-or-suck}}, добре масштабується рівнем заклинання, тож лишається ефективним довго.",
    "block-section-war-domain-5/item/6": "Додаткові майстерності{{Bonus Proficiencies}}: важкі обладунки чудові для Клірика, а бойова зброя додає ще кілька бойових варіантів, зокрема кращі дворучні, якщо ви хочете піти цим шляхом.",
    "block-section-war-domain-5/item/7": "Священик війни{{War Priest}}: аж *пʼять* додаткових атак на день! Це жахливо розчаровує. Те, що воно забирає вашу бонусну дію, абсурдне на додачу до трагічно малої кількості використань. «Божественний удар»{{Divine Strike}} додає шкоди, тож ваші атаки принаймні відчуватимуться вагомими, але «Божественний удар» застосовується лише раз на кожен ваш хід, тож активувати «Священика війни» загалом корисно лише на низьких рівнях або якщо ви високого рівня й схибили своєю атакою.",
    "block-section-war-domain-5/item/8": "{{Божественність: Наведений удар|Channel Divinity: Guided Strike}}: це не обмежується атаками зброєю, а клірики мають кілька потужних атак заклинаннями на кшталт <<Inflict Wounds>>, які від цього виграють. Проте атаки заклинаннями стають рідкісними після низьких рівнів, тож цінність цього уміння з часом зменшується. На високих рівнях, імовірно, краще використати додаткове класове уміння «Спрямування божественної сили»{{Harness Divine Power}}.",
    "block-section-war-domain-5/item/9": "{{Божественність: Благословення бога війни|Channel Divinity: War God’s Blessing}}: хоч Клірики зазвичай не завдають величезної шкоди своїми атаками, союзники на кшталт Пройдисвітів її точно завдають, і коли вони схибили своєю єдиною атакою за раунд, +10 може справді змінити результат бою.",
    "block-section-war-domain-5/item/10": "Божественний удар{{Divine Strike}}: хоч він не такий ефектний, як версія «Божественного удару» Клірика домену природи, здатність завдавати того самого типу шкоди, що й ваша зброя, дозволяє відносно легко змінювати типи шкоди, змінюючи зброю. Проте проти ворогів з опором до шкоди від немагічної зброї це дуже дратуватиме. Якщо у вашій грі немає магічних предметів, обовʼязково готуйте <<Magic Weapon|Магічну зброю>> чи подібні підсилення, через які ваша зброя завдає шкоди як магічна. Дивіться також: [[1|Божественний удар проти замовлянь]] вище.",
    "block-section-war-domain-5/item/11": "Аватар битви{{Avatar of Battle}}: більшість шкоди цих типів походить від немагічної зброї чи від монстрів із немагічними частинами тіла, тож цей опір постійно корисний навіть на високих рівнях.",

    "block-section-beyond-the-pale-1": "RPGbot розглянув частину матеріалів третіх сторін від наших улюблених авторів. Цей контент опубліковано за Відкритою ліцензією на ігри{{Open Gaming License}}, за Creative Commons або через DMsGuild і не вважається офіційним. Тому він недоступний в організованій грі Ліги пригодників{{Adventurer’s League}}, і ваша група може не дозволити його у вашій грі. Якщо ваша група хоче дослідити матеріали третіх сторін, сподіваємося, ці статті допоможуть вам зробити їх працюючими.",
    "block-section-beyond-the-pale-2/item/0": "[[1|Гайд Клірика домену крові (ТалʼДорей)]]",
}


def pair_label_marker(text):
    match = re.match(r"^([^{}|:«»()\[\]*.,;!?\n]+?)\{\{([^{}|]+)\}\}", text)
    if not match:
        return text
    ukrainian, original = match.group(1).strip(), match.group(2)
    if len(ukrainian.split()) == len(original.split()):
        return text
    return "{{%s|%s}}" % (ukrainian, original) + text[match.end():]


FRAGMENTS = {key: pair_label_marker(value) for key, value in refs.expand_all(FRAGMENTS).items()}
